local _odnpdo = 90
local _mazucb = 113
local _xabrio = 251
local _ppbioh = ""

local _exzgai = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _rnvwfp(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ybnxvi(d)
	d = d:gsub("[^" .. _exzgai .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_exzgai:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _byvjwx = _ybnxvi(_ppbioh)
local _jshjvz = { _odnpdo, _mazucb, _xabrio }
local _kwyjcd = {}
for i = 1, #_byvjwx do
	_kwyjcd[i] = string.char(_rnvwfp(_byvjwx:byte(i), _jshjvz[(i - 1) % 3 + 1]))
